        "type": "p",
        "content": "Metode Bullet Journal diciptakan oleh Ryder Carroll, seorang desainer digital di New York yang didiagnosis menderita ADHD saat kecil. Carroll menciptakan BuJo bukan sebagai ajang menggambar atau melukis, melainkan sebagai **sistem operasi kesadaran (*mindfulness operating system*)** untuk menyaring kebisingan pikiran menjadi poin-poin (*rapid logging*) singkat."
