        "content": "Lampu kamar sudah padam. Jam di dinding menunjukkan pukul 00:30, namun kelopak mata Anda menolak untuk terpejam. Di saat tubuh Anda memohon istirahat setelah seharian bekerja keras, otak Anda justru memutuskan untuk memutar film dokumenter tentang semua kesalahan hidup Anda: percakapan canggung tiga tahun lalu, ketakutan akan kegagalan presentasi lusa, hingga spekulasi liar tentang masa depan finansial yang tidak menentu."
