        "content": "Salah satu intervensi psikologis paling efektif yang telah divalidasi oleh penelitian neurosains adalah **Guided Journaling (Jurnal Terpandu)**. Dalam artikel ini, kita akan membedah mekanisme biologis di balik overthinking malam hari, mengapa cara-cara konvensional sering gagal, dan protokol 5 menit menulis reflektif untuk mematikan mode panik otak Anda sebelum tidur."
